class Solution {
    public List<List<Integer>> mergeSimilarItems(int[][] items1, int[][] items2) {
        int[] total = new int[1001];
        for (int[] it : items1) total[it[0]] += it[1];
        for (int[] it : items2) total[it[0]] += it[1];
        List<List<Integer>> res = new ArrayList<>();
        for (int v = 1; v <= 1000; v++)
            if (total[v] > 0) res.add(Arrays.asList(v, total[v]));
        return res;
    }
}

c.javascript:
var mergeSimilarItems = function(items1, items2) {
    const total = new Map();
    for (const [v, w] of [...items1, ...items2])
        total.set(v, (total.get(v) || 0) + w);
    return [...total.keys()].sort((a, b) => a - b)
        .map(v => [v, total.get(v)]);
};
